const tau=Math.PI*2;
function rect(w,h){const s=new THREE.Shape();s.moveTo(-w/2,-h/2);s.lineTo(w/2,-h/2);s.lineTo(w/2,h/2);s.lineTo(-w/2,h/2);s.closePath();return s;}
function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}
function rectHole(s,x,y,w,h){const p=new THREE.Path();p.moveTo(x-w/2,y-h/2);p.lineTo(x+w/2,y-h/2);p.lineTo(x+w/2,y+h/2);p.lineTo(x-w/2,y+h/2);p.closePath();s.holes.push(p);}
function extrude(parent,shape,depth,position,material,name){return mesh(parent,new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,curveSegments:48}),material,position,name);}
function electronics(host){
 const pcbMaterial=materials.plastic(0xe2e4db,{roughness:.9}),metal=materials.metal(0xb7b6a4,{roughness:.48}),dark=materials.plastic(0x191d18,{roughness:.84}),ceramic=materials.plastic(0x999575,{roughness:.85});
 const shape=new THREE.Shape();shape.moveTo(-10.35,-9.2);shape.lineTo(-8.7,-10.3);shape.lineTo(-5.5,-10.3);shape.lineTo(-5.5,-5.4);shape.lineTo(5.5,-5.4);shape.lineTo(5.5,-10.3);shape.lineTo(8.7,-10.3);shape.lineTo(10.35,-9.2);shape.lineTo(10.35,-3.6);shape.lineTo(8,-3.6);shape.absarc(8,0,3.6,-Math.PI/2,-Math.PI*1.5,true);shape.lineTo(10.35,3.6);shape.lineTo(10.35,8.5);shape.lineTo(9.1,9.9);shape.lineTo(-9.1,9.9);shape.lineTo(-10.35,8.5);shape.lineTo(-10.35,3.6);shape.lineTo(-8,3.6);shape.absarc(-8,0,3.6,Math.PI/2,-Math.PI/2,true);shape.lineTo(-10.35,-3.6);shape.closePath();hole(shape,0,0,1.8);
 const first=extrude(host.body,shape,.8,[0,0,-2.3],pcbMaterial,'Mini ToF-90 fixed1F horizontal Grove and regulator PCB');first.userData={role:'physical-pcb',board:'1F',inferred:true};
 const frame=new THREE.Group();frame.name='Mini ToF-90 fixed90-degree2F sensor board frame';frame.position.set(0,10.16,-1.2);frame.rotation.x=-Math.PI/2;host.body.add(frame);
 const second=extrude(frame,rect(8,4.6),.8,[0,0,0],pcbMaterial,'Mini ToF-90 fixed2F upright optical PCB');second.userData={role:'physical-pcb',board:'2F',inferred:true};
 const regulator=slab(host.body,1.6,2.9,.8,.08,[-7.4,6.2,-1.5],dark,[],.01);regulator.name='Mini ToF-90 U1 ME6206A33XG physical SOT23 regulator';for(const[dx,dy]of[[-1,-.8],[-1,.8],[1,0]])mesh(host.body,new THREE.BoxGeometry(.75,.4,.16),metal,[-7.4+dx,6.2+dy,-1.42],'Mini ToF-90 regulator metal terminal');
 const passives=[];for(const[x,y,mat]of[[-4.5,6.5,dark],[-4.5,4.7,dark],[4.6,7.4,ceramic],[-7.5,8.3,ceramic],[-7.5,3.5,ceramic],[7.9,-3.1,dark]]){passives.push(mesh(host.body,new THREE.BoxGeometry(1.55,.8,.5),mat,[x,y,-1.25],'Mini ToF-90 fixed1F resistor or decoupling capacitor'));for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.3,.8,.52),metal,[x+sign*.65,y,-1.25],'Mini ToF-90 passive solder termination');}
 for(const[x,y]of[[-2.9,1.65],[2.9,1.65]]){passives.push(mesh(frame,new THREE.BoxGeometry(1.2,.65,.45),dark,[x,y,1.025],'Mini ToF-90 fixed2F XSHUT and GPIO pull-up packages'));}
 for(const[x,y]of[[-2.9,-1.5],[2.9,-1.5]])passives.push(mesh(frame,new THREE.BoxGeometry(1.2,.65,.55),ceramic,[x,y,1.075],'Mini ToF-90 fixed2F local decoupling capacitor'));
 const p1=mesh(host.body,new THREE.BoxGeometry(8.2,1.4,1.2),dark,[0,8.9,-.9],'Mini ToF-90 P1 fixed four-pin board-link dielectric');
 const p2=mesh(frame,new THREE.BoxGeometry(8.2,1.25,.75),dark,[0,-.3,-.4],'Mini ToF-90 P2 fixed four-pin board-link dielectric');
 const links=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;const vertical=mesh(host.body,new THREE.BoxGeometry(.38,.38,1.4),metal,[x,8.9,-.8],`Mini ToF-90 P1/P2 physical pin${i+1} vertical leg`),horizontal=mesh(host.body,new THREE.BoxGeometry(.38,1.6,.38),metal,[x,9.51,-.1],`Mini ToF-90 P1/P2 physical pin${i+1} right-angle leg`);links.push({vertical,horizontal});}
 const d1=mesh(host.body,new THREE.BoxGeometry(1.6,.8,.6),materials.plastic(0x882a22,{roughness:.6}),[7.9,-5,-1.2],'Mini ToF-90 D1 documented red power LED physical package');d1.userData={role:'physical-led-package',reference:'D1',emitsVisibleLight:true,positionInferred:true};
 return{first,second,frame,regulator,passives,p1,p2,links,d1};
}
function optical(host,pcb){
 const frame=new THREE.Group();frame.name='Mini ToF-90 U2 fixed forward optical LGA12 frame';frame.position.z=.8;pcb.frame.add(frame);
 const dark=materials.plastic(0x1e2220,{roughness:.73}),black=materials.plastic(0x0f1413,{roughness:.88}),glass=materials.plastic(0x222b33,{roughness:.18,metalness:.1}),metal=materials.metal(0x999b8f,{roughness:.5});
 const substrate=mesh(frame,new THREE.BoxGeometry(4.4,2.4,.5),dark,[0,0,.25],'Mini ToF-90 real VL53L0CXV0DH/1 optical package substrate');
 const apertures=[{x:-1.22,y:0,w:.64,h:.64,role:'emitter'},{x:.72,y:0,w:1.45,h:1.45,role:'receiver'}],shape=rect(4.4,2.4);for(const a of apertures)rectHole(shape,a.x,a.y,a.w,a.h);
 const baffle=extrude(frame,shape,.5,[0,0,.5],black,'Mini ToF-90 package front baffle with actual separated emitter and receiver cavities');baffle.userData={role:'optical-baffle',apertureDimensionsInferred:true};
 const windows=apertures.map(a=>{const o=mesh(frame,new THREE.BoxGeometry(a.w-.06,a.h-.06,.08),glass,[a.x,a.y,.74],`Mini ToF-90 passive non-emissive ${a.role} optical window`);o.userData={role:'passive-optical-window',opticalRole:a.role,invisibleInfrared:true};return o;});
 const pads=[];for(let row of[-1,1])for(let i=0;i<6;i++)pads.push(mesh(frame,new THREE.BoxGeometry(.32,.32,.08),metal,[(i-2.5)*.65,row*1.06,.04],`Mini ToF-90 LGA12 fixed metal land${pads.length+1}`));
 const surroundShape=rect(8.1,4.25);rectHole(surroundShape,0,0,4.45,2.45);const surround=extrude(frame,surroundShape,.7,[0,0,.05],black,'Mini ToF-90 fixed black optical opening surround and deep cavity backing');
 return{frame,substrate,baffle,windows,pads,surround,apertures};
}
function grove(host){const g=new THREE.Group();g.name='Mini ToF-90 real red HY2.0-4P Grove housing';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const red=materials.plastic(spec.grove.color,{roughness:.72}),metal=materials.metal(0xb7b39e,{roughness:.4}),box=(s,p,n,m=red)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'Mini ToF-90 Grove '+n),depth=6.1;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.5],'inner guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}
 box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.3],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.3],[(i-1.5)*2,.2,-3.5],`real contact${i+1}`,metal));box([.42,1.3,.42],[(i-1.5)*2,-2.65,-5.6],`solder tail${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.A · I2C',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Four physical contacts and cable attachment/pose only;no I2C,voltage,power,electrical,range or firmware simulation'}}));return{group:g,port,contacts};}
/** Native enclosed insert has no camera-facing halo;brightness changes its material only. */
class PowerLed extends Component{static kind='led';constructor(lens){super({id:'power-led',label:'D1 red power indicator appearance',meta:{role:'appearance-output',reference:'D1 RED LED',fixedColor:true,defaultOff:true,noHalo:true,guideMaterialAndCouplingInferred:true,scope:'External on/brightness only;red is documented by own schematic.Native Grove-side guide material and coupling inferred.No power/voltage or automatic connection state.'}});this.lens=lens;this.brightness=0;this.lens.material.emissive=new THREE.Color(0);}
 set(state){if(typeof state==='boolean')state={on:state};if(typeof state==='string'||typeof state==='number')state={on:true};if(state.brightness!=null){if(!Number.isFinite(state.brightness))throw new TypeError('power-led brightness must be finite');this.brightness=Math.max(0,Math.min(1,state.brightness));}else if(state.on!=null)this.brightness=state.on?1:0;this.lens.material.emissive.setHex(0xff2020).multiplyScalar(this.brightness*2.2);this.requestRender();}
 handle(cmd){if(cmd.type!=='led')return super.handle(cmd);this.set(cmd);}getState(){return{color:'#ff2020',brightness:this.brightness};}}
export function buildMiniToF90(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe7e8e2,{roughness:.8}),insert:materials.plastic(0xd5d9ce,{roughness:.43})}),pcb=electronics(host),sensor=optical(host,pcb),input=grove(host),guide=parts['Mini ToF-90 complete native Grove-side insert'];const led=host.add(new PowerLed(guide));
 const labels={};for(const[face,z]of[['front',3.77],['back',-3.93]]){const film=slab(host.body,18.8,4.8,.12,.3,[0,7.7,z],materials.plastic(0xf0f1eb,{roughness:.85}),[],.005);film.name=`Mini ToF-90 physical ${face} adhesive substrate bridging native print recess`;film.userData={role:'physical-label-substrate',face};labels[face]=film;}
 const fixing=screw(host.body,[0,0,-3.82],'back',1.27);fixing.name='Mini ToF-90 actual recessed central retaining screw';mesh(host.body,new THREE.CylinderGeometry(.6,.6,3.9,32).rotateX(Math.PI/2),materials.metal(0x9e9f96),[0,0,-1.7],'Mini ToF-90 concealed central retaining screw shank');
 const anchor=host.add(new Component({id:'sensor',label:'Fixed90° VL53L0X optical appearance anchor',position:[0,11.96,-1.2],quaternion:FACE.top,meta:{role:'visual-anchor',part:'VL53L0CXV0DH/1',fixedBoardAngleDeg:90,outward:[0,1,0],scope:'Passive anchor only;no distance/value,IR beam,visible infrared,cone,FoV rendering,tilt,joint,register,I2C,electrical or firmware commands'}}));
 host.miniToF90Assembly={parts,pcb,sensor,input,guide,led,labels,fixing,anchor};host.unitStickers=addStickers(host);}
